 import "strings"

-func Produce(lines []string) []string {
-    out := make([]string, 0, len(lines))
-    for _, line := range lines { out = append(out, strings.TrimSpace(line)) }
+type Record struct { ID int; Text string }
+
+func Produce(lines []string) []Record {
+    out := make([]Record, 0, len(lines))
+    for i, line := range lines {
+        text := strings.TrimSpace(line)
+        if text != "" { out = append(out, Record{ID:i+1, Text:text}) }
+    }
     return out
 }
+
+func Stats(lines []string) (kept int, dropped int) {
+    kept = len(Produce(lines))
+    return kept, len(lines)-kept
+}
+
+func Duplicates(lines []string) []string {
+    records := Produce(lines)
+    counts := map[string]int{}
+    for _, record := range records { counts[record.Text]++ }
+    out := []string{}
+    for _, record := range records {
+        if counts[record.Text] > 1 { out = append(out, record.Text); counts[record.Text] = 0 }
+    }
+    return out
+}
